#!/bin/sh
# Fixed image core environment; explicit per-process selections take precedence.
if [ -z "${KIO_TOOLCHAIN_IDENTITY:-}" ] && [ -r /opt/kio-toolchain/environment.sh ]; then
  # shellcheck disable=SC1091 # Generated by the image provisioning step.
  . /opt/kio-toolchain/environment.sh
fi

# The editor uses KIO_BIN; interactive terminals also expose checkout binaries.
case $- in
  *i*)
    _kio_checkout=$(git rev-parse --show-toplevel 2>/dev/null) || _kio_checkout=
    if [ -n "$_kio_checkout" ] && [ -d "$_kio_checkout/kio-rs" ]; then
      PATH="$_kio_checkout/kio-rs/target/release:$_kio_checkout/kio-rs/target/debug:$PATH"
      export PATH
    fi
    unset _kio_checkout ;;
esac
